P.pengaturan=async()=>{const [a,b,c,d]=await Promise.all([sb.from('pengaturan').select('data').eq('key','site').maybeSingle(),sb.from('berita').select('*').order('tanggal',{ascending:false}),sb.from('galeri').select('*').order('created_at',{ascending:false}),sb.from('tahfidz').select('*')]);
 const s=a.data?.data||{};
 $('#main').innerHTML=`<h1 class="h mb-3">Pengaturan Web Publik</h1>
 <form id="fs" class="card"><b>Profil, Visi, Misi & Kontak</b>${inp('nama','Nama Sekolah',s.nama)}${inp('tagline','Slogan',s.tagline)}${inp('kartu_sub','Teks di bawah nama sekolah pada Kartu Pelajar',s.kartu_sub??'Kec. Krucil Kab. Probolinggo')}${ta('profil','Profil Sekolah',s.profil,5)}${ta('visi','Visi',s.visi)}${ta('misi','Misi (satu baris = satu poin)',s.misi,5)}${inp('alamat','Alamat',s.alamat)}${inp('telp','Telepon',s.telp)}${inp('email','Email',s.email,'email')}${inp('wa','No. WhatsApp (628xxx)',s.wa)}${inp('yt','Link YouTube',s.yt,'url')}${inp('tiktok','Link TikTok',s.tiktok,'url')}${inp('wachan','Link Channel WhatsApp',s.wachan,'url')}
  <label class="block text-sm mt-2">Logo ${s.logo?`<img src="${esc(s.logo)}" class="h-10 inline">`:''}<input type="file" name="logo" accept="image/*" class="inp"></label><label class="block text-sm mt-2">Foto Sekolah ${s.hero?`<img src="${esc(s.hero)}" class="h-10 inline">`:''}<input type="file" name="hero" accept="image/*" class="inp"></label><label class="block text-sm mt-2">Foto Latar Beranda ${s.bg?`<img src="${esc(s.bg)}" class="h-10 inline">`:''}<input type="file" name="bg" accept="image/*" class="inp"></label>${inp('bgop','Ketebalan foto latar (10 = sangat transparan, 90 = tebal)',s.bgop??40,'number','min=10 max=90')}<button class="btn mt-4">Simpan Pengaturan</button></form>
 <div class="card"><div class="flex items-center mb-2"><b class="mr-auto">Berita & Pengumuman</b><button id="ab" class="btn">＋ Tambah</button></div><div class="divide-y text-sm">${b.data.map(x=>`<div class="py-2 flex gap-2"><span class="text-xs bg-slate-100 rounded px-1 h-fit">${x.jenis}</span><span class="flex-1">${esc(x.judul)}</span><button data-be="${x.id}" class="text-indigo-600">Edit</button><button data-bd="${x.id}" class="text-red-600">Hapus</button></div>`).join('')||'<p class="text-slate-400">Belum ada.</p>'}</div></div>
 <div class="card"><b>Galeri Kegiatan</b><label class="block text-sm mt-2">Unggah foto (boleh banyak)<input id="gu" type="file" accept="image/*" multiple class="inp"></label><div class="grid grid-cols-3 md:grid-cols-6 gap-2 mt-3">${c.data.map(x=>`<div class="relative"><img loading="lazy" src="${esc(x.url)}" class="aspect-square object-cover rounded-lg"><button data-ge="${x.id}" class="absolute top-1 left-1 bg-white/90 rounded px-1 text-xs text-indigo-600">✎</button><button data-gd="${x.id}" class="absolute top-1 right-1 bg-white/90 rounded px-1 text-xs text-red-600">✕</button></div>`).join('')}</div></div>`;
 const TM=Object.fromEntries((d.data||[]).map(x=>[x.kelas,x.url]));
 $('#main').insertAdjacentHTML('beforeend',`<form id="ft" class="card"><b>📖 Link Hafalan Tahfidz</b><p class="text-xs text-slate-500">Tempel link aplikasi tahfidz. "Umum" dipakai bila kelas tidak punya link sendiri. Kosongkan kolom untuk menghapus link.</p>${inp('k0','Umum (semua kelas)',TM[0],'url')}${KLS.map(k=>inp('k'+k,'Kelas '+k,TM[k],'url')).join('')}<button class="btn mt-4">Simpan Link</button></form>`);
 $('#ft').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target));try{for(const k of [0,...KLS]){const u=(f['k'+k]||'').trim();if(u){if(!/^https?:\/\//i.test(u))throw new Error('Link harus diawali http:// atau https://');const {error}=await sb.from('tahfidz').upsert({kelas:k,url:u});if(error)throw error}else{await sb.from('tahfidz').delete().eq('kelas',k)}}alert('Link tersimpan');go()}catch(x){alert(x.message)}};
 $('#fs').onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.target)),d={...s,...f};
  try{for(const n of['logo','hero','bg']){if(f[n]?.size)d[n]=await up(f[n],n==='logo');else d[n]=s[n]}const {error}=await sb.from('pengaturan').upsert({key:'site',data:d});if(error)throw error;alert('Tersimpan');go()}catch(x){alert(x.message)}};
 const bf=x=>sel('jenis','Jenis',[['berita','Berita'],['pengumuman','Pengumuman']],x?.jenis)+inp('judul','Judul',x?.judul,'text','required')+inp('tanggal','Tanggal',x?.tanggal||today(),'date')+ta('isi','Isi',x?.isi||'',7)+`<label class="block text-sm mt-2">Gambar ${x?.gambar?'(kosongkan jika tidak diganti)':'(opsional)'}<input type="file" name="gambar" accept="image/*" class="inp"></label>`;
 const bs=x=>async f=>{const d={jenis:f.jenis,judul:f.judul,tanggal:f.tanggal||today(),isi:f.isi.trim()};if(f.gambar?.size)d.gambar=await up(f.gambar);const {error}=x?await sb.from('berita').update(d).eq('id',x.id):await sb.from('berita').insert(d);if(error)throw error;go()};
 $('#ab').onclick=()=>modal('Tambah Berita / Pengumuman',bf(),bs());
 document.querySelectorAll('[data-be]').forEach(bt=>bt.onclick=()=>{const x=b.data.find(y=>y.id===bt.dataset.be);modal('Edit Berita / Pengumuman',bf(x),bs(x))});
 document.querySelectorAll('[data-ge]').forEach(bt=>bt.onclick=()=>{const g=c.data.find(y=>y.id===bt.dataset.ge);modal('Edit Foto Galeri',inp('judul','Keterangan',g.judul)+`<label class="block text-sm mt-2">Ganti foto (opsional)<input type="file" name="url" accept="image/*" class="inp"></label>`,async f=>{const d={judul:f.judul};if(f.url?.size)d.url=await up(f.url);const {error}=await sb.from('galeri').update(d).eq('id',g.id);if(error)throw error;go()})});
 document.querySelectorAll('[data-bd]').forEach(x=>x.onclick=async()=>{if(confirm('Hapus?')){await sb.from('berita').delete().eq('id',x.dataset.bd);go()}});
 document.querySelectorAll('[data-gd]').forEach(x=>x.onclick=async()=>{if(confirm('Hapus foto?')){await sb.from('galeri').delete().eq('id',x.dataset.gd);go()}});
 $('#gu').onchange=async ev=>{try{for(const f of ev.target.files){await sb.from('galeri').insert({judul:f.name,url:await up(f)})}go()}catch(x){alert(x.message)}}};
